  var !type!List<string>!/type!words := !type!string!/type!sentence.!type!array of string!/type!Split(' ').!type!List<string>!/type!ToList;
  var !type!List<string>!/type!primeWords := new List<string>;

  foreach var word in !type!List<string>!/type!words do
  begin
    var !type!integer!/type!length := !type!string!/type!word.!type!integer!/type!Length;
    var !type!boolean!/type!isPrime := !type!boolean!/type!True;

    for var i := 2 to !type!integer!/type!Round(!type!real!/type!Sqrt(!type!integer!/type!length)) do
      if !type!integer!/type!length mod !type!integer!/type!i = 0 then
      begin
        !type!boolean!/type!isPrime := !type!boolean!/type!False;
        break;
      end;

    if !type!boolean!/type!isPrime then
      !type!List<string>!/type!primeWords.Add(!type!string!/type!word);
  end;

  var !type!List<string>!/type!primeWordsSorted := !type!List<string>!/type!primeWords.!type!IOrderedEnumerable<string>!/type!OrderBy(!type!string!/type!word -> !type!string!/type!word).!type!List<string>!/type!ToList;
  var !type!string!/type!result := '';

  for var i := 0 to !type!List<string>!/type!primeWordsSorted.!type!integer!/type!Count - 1 do
  begin
    if !type!integer!/type!i <> 0 then
      !type!string!/type!result += ' ';
    !type!string!/type!result += !type!List<string>!/type!primeWordsSorted[!type!integer!/type!i];
  end;

  !type!string!/type!Result := !type!string!/type!result;
end;

begin
end.




function Simplify(x, n: string): boolean;
begin
  var !type!string!/type!x1 := '';
  var !type!string!/type!n1 := '';
  var !type!integer!/type!i := 1;
  while !type!integer!/type!i <= !type!string!/type!x.!type!integer!/type!Length do
  begin
    !type!string!/type!x1 += !type!string!/type!x[!type!integer!/type!i].!type!string!/type!ToString;
    !type!integer!/type!i += 1;
  end;
  while !type!integer!/type!i <= !type!string!/type!n.!type!integer!/type!Length do
  begin
    !type!string!/type!n1 += !type!string!/type!n[!type!integer!/type!i].!type!string!/type!ToString;
    !type!integer!/type!i += 1;
  end;
  var !type!integer!/type!x1 := !type!integer!/type!StrToInt(!type!string!/type!x1);
  var !type!integer!/type!n1 := !type!integer!/type!StrToInt(!type!string!/type!n1);
  if (!type!integer!/type!x1 mod !type!integer!/type!n1 = 0) then
    !type!boolean!/type!Result := !type!boolean!/type!True
  else
    !type!boolean!/type!Result := !type!boolean!/type!False;
end;

begin
end.




function OrderByPoints(nums: array of integer): array of integer;
begin
  var !type!array of integer!/type!sorted := !type!array of integer!/type!nums.!type!array of integer!/type!ToArray;
  !type!array of integer!/type!sorted.Sort((!type!integer!/type!x, !type!integer!/type!y) ->
  begin
    var !type!integer!/type!xSum := !type!integer!/type!x.!type!string!/type!ToString.!type!integer!/type!Sum(!type!char!/type!c -> !type!integer!/type!StrToInt(!type!char!/type!c.!type!string!/type!ToString));
    var !type!integer!/type!ySum := !type!integer!/type!y.!type!string!/type!ToString.!type!integer!/type!Sum(!type!char!/type!c -> !type!integer!/type!StrToInt(!type!char!/type!c.!type!string!/type!ToString));
    if !type!integer!/type!xSum = !type!integer!/type!ySum then
      !type!integer!/type!Result := !type!array of integer!/type!nums.!type!integer!/type!IndexOf(!type!integer!/type!x) - !type!array of integer!/type!nums.!type!integer!/type!IndexOf(!type!integer!/type!y)
    else
      !type!integer!/type!Result := !type!integer!/type!xSum - !type!integer!/type!ySum;
  end);
  !type!array of integer!/type!Result := !type!array of integer!/type!sorted;
end;

begin
end.




