  var !type!array of integer!/type!a := new integer[!type!integer!/type!n];
  for var i := 0 to !type!integer!/type!n - 1 do
    !type!array of integer!/type!a[!type!integer!/type!i] := !type!integer!/type!i * !type!integer!/type!i - !type!integer!/type!i + 1;
  var !type!integer!/type!count := 0;
  for var i := 0 to !type!integer!/type!n - 2 do
    for var j := !type!integer!/type!i + 1 to !type!integer!/type!n - 1 do
      for var k := !type!integer!/type!j + 1 to !type!integer!/type!n - 1 do
        if (!type!array of integer!/type!a[!type!integer!/type!i] + !type!array of integer!/type!a[!type!integer!/type!j] + !type!array of integer!/type!a[!type!integer!/type!k]) mod 3 = 0 then
          !type!integer!/type!count += 1;
