end.




function Bf(planet1, planet2: string): array of string;
begin
  var !type!array of string!/type!planets := |'Mercury', 'Venus', 'Earth', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune'|;
  var !type!List<string>!/type!res := new List<string>;
  var !type!integer!/type!index1 := -1;
  var !type!integer!/type!index2 := -1;
  for var i := 0 to !type!array of string!/type!planets.!type!integer!/type!Length - 1 do
  begin
    if !type!array of string!/type!planets[!type!integer!/type!i] = !type!string!/type!planet1 then
      !type!integer!/type!index1 := !type!integer!/type!i
    else if !type!array of string!/type!planets[!type!integer!/type!i] = !type!string!/type!planet2 then
      !type!integer!/type!index2 := !type!integer!/type!i;
  end;
  if (!type!integer!/type!index1 = -1) or (!type!integer!/type!index2 = -1) then
  begin
    !type!array of string!/type!Result := new string[0];
    exit;
  end;
  if !type!integer!/type!index1 > !type!integer!/type!index2 then
  begin
    var !type!integer!/type!temp := !type!integer!/type!index1;
    !type!integer!/type!index1 := !type!integer!/type!index2;
    !type!integer!/type!index2 := !type!integer!/type!temp;
  end;
  for var i := !type!integer!/type!index1 to !type!integer!/type!index2 do
    !type!List<string>!/type!res.Add(!type!array of string!/type!planets[!type!integer!/type!i]);
  !type!array of string!/type!Result := !type!List<string>!/type!res.!type!array of string!/type!ToArray;
end;

begin
end.




function SortedListSum(lst: array of string): array of string;
begin
  var !type!List<string>!/type!filtered := new List<string>;
  foreach var word in !type!array of string!/type!lst do
    if !type!string!/type!word.!type!integer!/type!Length mod 2 = 0 then
      !type!List<string>!/type!filtered.Add(!type!string!/type!word);

  !type!List<string>!/type!filtered.Sort((!type!string!/type!x, !type!string!/type!y) ->
  begin
    if !type!string!/type!x.!type!integer!/type!Length <> !type!string!/type!y.!type!integer!/type!Length then
      !type!integer!/type!Result := !type!string!/type!x.!type!integer!/type!Length.!type!integer!/type!CompareTo(!type!string!/type!y.!type!integer!/type!Length)
    else
      !type!integer!/type!Result := !type!string!/type!x.!type!string!/type!CompareTo(!type!string!/type!y);
  end);

  !type!array of string!/type!Result := !type!List<string>!/type!filtered.!type!array of string!/type!ToArray;
end;

begin
end.




