function DoubleTheDifference(lst: array of real): integer;
begin
  var !type!integer!/type!sum := 0;
  foreach var num in !type!array of real!/type!lst do
    if !type!real!/type!num < 0 then
      continue;
    if !type!integer!/type!num mod 2 <> 0 then
      !type!integer!/type!sum += !type!integer!/type!num * !type!integer!/type!num;
  !type!integer!/type!Result := !type!integer!/type!sum;
end;

