  begin
    if !type!array of integer!/type!game[!type!integer!/type!i] = !type!array of integer!/type!guess[!type!integer!/type!i] then
      !type!List<integer>!/type!res.Add(0)
    else
      !type!List<integer>!/type!res.Add(!type!integer!/type!Abs(!type!array of integer!/type!game[!type!integer!/type!i] - !type!array of integer!/type!guess[!type!integer!/type!i]));
