end.




function StrongestExtension(className: string; extensions: array of string): string;
begin
  var !type!integer!/type!maxStrength := -1000000;
  var !type!string!/type!strongestExtension := '';
  foreach var extension in !type!array of string!/type!extensions do
  begin
    var !type!integer!/type!cap := 0;
    var !type!integer!/type!sm := 0;
    for var i := 1 to !type!string!/type!extension.!type!integer!/type!Length do
    begin
      if Char.!type!boolean!/type!IsUpper(!type!string!/type!extension[!type!integer!/type!i]) then
        !type!integer!/type!cap += 1;
      if Char.!type!boolean!/type!IsLower(!type!string!/type!extension[!type!integer!/type!i]) then
        !type!integer!/type!sm += 1;
    end;
    var !type!integer!/type!strength := !type!integer!/type!cap - !type!integer!/type!sm;
    if !type!integer!/type!strength > !type!integer!/type!maxStrength then
    begin
      !type!integer!/type!maxStrength := !type!integer!/type!strength;
      !type!string!/type!strongestExtension := !type!string!/type!extension;
    end;
  end;
  !type!string!/type!Result := !type!string!/type!className + '.' + !type!string!/type!strongestExtension;
end;

begin
end.




