function IntToMiniRoman(number: integer): string;
begin
  var !type!array of string!/type!roman := new string[](
    'm', 'cm', 'd', 'cd', 'c', 'xc', 'l', 'xl', 'x', 'ix', 'v', 'iv', 'i'
  );
