    1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1
  );

  var !type!string!/type!romanNum := '';
  var !type!integer!/type!i := 0;

  while !type!integer!/type!number > 0 do
  begin
    for var j := 1 to !type!integer!/type!number div !type!array of integer!/type!values[!type!integer!/type!i] do
    begin
      !type!string!/type!romanNum += !type!array of string!/type!roman[!type!integer!/type!i];
      !type!integer!/type!number -= !type!array of integer!/type!values[!type!integer!/type!i];
