function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var !type!integer!/type!result := !type!array of integer!/type!operand[0];
  for var i := 0 to !type!array of string!/type!op.!type!integer!/type!Length - 1 do
  begin
    case !type!array of string!/type!op[!type!integer!/type!i] of
      '+': !type!integer!/type!result := !type!integer!/type!result + !type!array of integer!/type!operand[!type!integer!/type!i + 1];
      '-': !type!integer!/type!result := !type!integer!/type!result - !type!array of integer!/type!operand[!type!integer!/type!i + 1];
      '*': !type!integer!/type!result := !type!integer!/type!result * !type!array of integer!/type!operand[!type!integer!/type!i + 1];
      '//': !type!integer!/type!result := !type!integer!/type!result div !type!array of integer!/type!operand[!type!integer!/type!i + 1];
      '**': !type!integer!/type!result := !type!integer!/type!result * !type!array of integer!/type!operand[!type!integer!/type!i + 1];
    end;
  end;
  !type!integer!/type!Result := !type!integer!/type!result;
end;

begin
end.











































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































